from cadquery import importers
import math

def report(name, path):
    imp = importers.importStep(path)
    solids = imp.solids().vals()
    print(f'===== {name} =====  实体数={len(solids)}')
    for i, s in enumerate(solids):
        b = s.BoundingBox()
        print(f'  实体{i}: X[{b.xmin:.2f},{b.xmax:.2f}] Y[{b.ymin:.2f},{b.ymax:.2f}] Z[{b.zmin:.2f},{b.zmax:.2f}]  尺寸 {b.xlen:.1f}x{b.ylen:.1f}x{b.zlen:.1f}')
