                    g = f._geomAdaptor()
                    cyl = g.Cylinder()
                    r = cyl.Radius()
                    loc = cyl.Location()
                    ax = cyl.Axis().Direction()
                    if r <= 6.0:
                        key = (round(r,2), round(loc.X(),1), round(loc.Y(),1), round(loc.Z(),1), round(ax.X(),1), round(ax.Y(),1), round(ax.Z(),1))
