import sys, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')
from cadquery import importers

solids = importers.importStep(r'E:\小车设计\AGV\新设计思路\电机支架.STEP').solids().vals()
print(f'实体数={len(solids)}')
for i, s in enumerate(solids):
    b = s.BoundingBox()
    print(f'实体{i}: X[{b.xmin:.2f},{b.xmax:.2f}] Y[{b.ymin:.2f},{b.ymax:.2f}] Z[{b.zmin:.2f},{b.zmax:.2f}]')
    print(f'   尺寸 {b.xlen:.1f} x {b.ylen:.1f} x {b.zlen:.1f}  体积{s.Volume()/1000:.1f}cm3')

# 所有圆柱面(孔和圆角)
seen = {}
for s in solids:
    for f in s.Faces():
        try:
            t = f.geomType()
            if t == 'CYLINDER':
                g = f._geomAdaptor().Cylinder()
                r = g.Radius(); loc = g.Location(); ax = g.Axis().Direction()
                key = ('CYL', round(r,2), round(loc.X(),1), round(loc.Y(),1), round(loc.Z(),1),
                       round(abs(ax.X()),1), round(abs(ax.Y()),1), round(abs(ax.Z()),1))
                seen[key] = seen.get(key,0)+1
        except Exception:
            pass
print('圆柱面 (r, 位置, |轴向|):')
for k in sorted(seen, key=lambda x:-x[1]):
    print(f'  r={k[1]}  pos=({k[2]},{k[3]},{k[4]})  axis=({k[5]},{k[6]},{k[7]})  面数{seen[k]}')
# 平面统计(找板厚)
planes = {}
for s in solids:
    for f in s.Faces():
        if f.geomType() == 'PLANE':
            n = f.normalAt()
            key = (round(abs(n.x),1), round(abs(n.y),1), round(abs(n.z),1))
            planes[key] = planes.get(key,0)+1
print('平面法向统计:', planes)

